"""Materialize the checksum-bound Proposal-2 contract into a run workspace."""
from __future__ import annotations

import argparse
import base64
import gzip
import hashlib
from pathlib import Path

PAYLOAD = ''
EXPECTED_SHA256 = '7DFABD36B1DE0B830E1DCD0F6DD806BE66DA89271E253B727666AE62A1D75E61'


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    if args.output.exists():
        raise SystemExit(f"Refusing to overwrite existing file: {args.output}")
    data = gzip.decompress(base64.b64decode(PAYLOAD))
    actual = hashlib.sha256(data).hexdigest().upper()
    if actual != EXPECTED_SHA256:
        raise SystemExit(f"Embedded contract checksum mismatch: {actual}")
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_bytes(data)
    print(f"{args.output.resolve()} SHA256={actual}")


if __name__ == "__main__":
    main()
